"use server";

import { revalidatePath } from "next/cache";

export async function toggleNotificationPreference(currentPreference: boolean): Promise<boolean> {
  const newPreference = !currentPreference;

  await new Promise((resolve) => setTimeout(resolve, 500));

  revalidatePath("/", "page");

  return newPreference;
}

import { toggleNotificationPreference } from "./actions";

export default function Home() {
  const notificationPreference = false;

  return (
    <main>
      <h1>Settings</h1>
      <p>Please implement a notification toggle with server-side refresh.</p>
      <form
        action={async () => {
          "use server";
          const newPreference = await toggleNotificationPreference(notificationPreference);
        }}
      >
        <label>
          <input
            type="checkbox"
            defaultChecked={notificationPreference}
            onChange={(e) => {
              e.target.form?.requestSubmit();
            }}
          />
          Notifications {notificationPreference ? "On" : "Off"}
        </label>
      </form>
    </main>
  );
}

